export function buildEngStructuredM(): McqQuestion[] {
  const list: McqQuestion[] = [];
  let seq = 1;
  const nextId = () => `eng_m_${String(seq++).padStart(4, '0')}`;

  // 1. 120 Phrasal / Appropriate Prepositions × 2 angles = 240 MCQs
  PHRASAL_BANK_M.forEach((p, idx) => {
    const diff = idx % 3 === 0 ? 'medical' : idx % 3 === 1 ? 'dental' : 'board';

    // Angle 1: Fill in preposition
    list.push(
      buildMcq({
        id: nextId(),
        subjectId: 'eng',
        medicalGroup: 'eng',
        chapterId: 'eng_vocab_prep',
        visualLessonId: 'english_grammar',
        hscLevel: 'admission',
        difficulty: diff,
        question: `Choose the appropriate preposition: "${p.sent}"`,
        correct: p.prep,
        distractors: p.wrongPreps,
        explanation: `"${p.pv}" একটি প্রমিত Appropriate Preposition / Group Verb যার অর্থ "${p.meaning}"।`,
        reference: 'Medical English · Appropriate Prepositions & Phrasal Verbs',
      })
    );

    // Angle 2: Bengali meaning
    const meaningWrongs = [
      PHRASAL_BANK_M[(idx + 7) % PHRASAL_BANK_M.length].meaning,
      PHRASAL_BANK_M[(idx + 19) % PHRASAL_BANK_M.length].meaning,
      PHRASAL_BANK_M[(idx + 37) % PHRASAL_BANK_M.length].meaning,
    ];
    list.push(
      buildMcq({
        id: nextId(),
        subjectId: 'eng',
        medicalGroup: 'eng',
        chapterId: 'eng_vocab_prep',
        visualLessonId: 'english_grammar',
        hscLevel: 'admission',
        difficulty: 'board',
        question: `What does the phrasal expression "${p.pv}" mean in Bengali?`,
        correct: p.meaning,
        distractors: meaningWrongs,
        explanation: `"${p.pv}" ব্যবহারের অর্থ হলো "${p.meaning}"। উদাহরণ: ${p.sent.replace('___', p.prep)}`,
        reference: 'Medical English · Phrasal Verb Semantics',
      })
    );
  });

  // 2. 120 Idioms & Phrases × 2 angles = 240 MCQs
  IDIOM_BANK_M.forEach((idItem, idx) => {
    const diff = idx % 2 === 0 ? 'medical' : 'dental';

    // Angle 1: Contextual Sentence Completion
    list.push(
      buildMcq({
        id: nextId(),
        subjectId: 'eng',
        medicalGroup: 'eng',
        chapterId: 'eng_vocab_prep',
        visualLessonId: 'english_grammar',
        hscLevel: 'admission',
        difficulty: diff,
        question: `Select the idiom that best completes the sentence: "${idItem.sent}"`,
        correct: idItem.idiom,
        distractors: [
          IDIOM_BANK_M[(idx + 5) % IDIOM_BANK_M.length].idiom,
          IDIOM_BANK_M[(idx + 17) % IDIOM_BANK_M.length].idiom,
          IDIOM_BANK_M[(idx + 31) % IDIOM_BANK_M.length].idiom,
        ],
        explanation: `"${idItem.idiom}" (${idItem.bn}) অর্থ "${idItem.meaning}", যা বাক্যের ভাবের সাথে সম্পূর্ণ মানানসই।`,
        reference: 'Medical English · Idioms in Context',
      })
    );

    // Angle 2: Meaning match
    list.push(
      buildMcq({
        id: nextId(),
        subjectId: 'eng',
        medicalGroup: 'eng',
        chapterId: 'eng_vocab_prep',
        visualLessonId: 'english_grammar',
        hscLevel: 'admission',
        difficulty: diff,
        question: `What is the exact meaning of the idiom "${idItem.idiom}" (${idItem.bn})?`,
        correct: idItem.meaning,
        distractors: idItem.wrongs,
        explanation: `ইংরেজি বাগধারা "${idItem.idiom}" বলতে বোঝায় "${idItem.meaning}" (${idItem.bn})।`,
        reference: 'Medical English · Idioms & Phrases',
      })
    );
  });

  return list;
}
